use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let data = input.as_array().unwrap();
    let mut ids = Vec::new();
    let mut priorities = Vec::new();

    for item in data {
        let priority = item[0].as_i64().unwrap();
        let id = item[1].as_i64().unwrap();
        ids.push(id);
        priorities.push(priority);
    }

    let mut sorted_ids = ids.clone();
    sorted_ids.sort_by(|a, b| {
        if priorities[a] == priorities[b] {
            sorted_ids[a] = b;
            sorted_ids[b] = a;
        }
        priorities[a].cmp(&priorities[b])
    });

    Value::Array(sorted_ids)
}
